import { personalConcern, repairTerms } from './people-context.js';
import { voiceProfile } from './character-voice.js';
export function peopleScene(s,p){
 const c=personalConcern(s,p);if(!c||s.age<18||p.age<18||s.conversations.seen.includes(`${p.id}:${c.key}`))return null;
 const profile=voiceProfile(s,p),identity=c.identity,place=s.world.locations.find(q=>q.id===p.locationId)?.name||'their home',here=s.world.locations.find(q=>q.id===s.locationId)?.name||'your current stop';
 const opening={kind:'I was hoping for time to tell you this.',driven:'Here is the next part I want to get right.',reserved:'There is something I have been thinking about.',bold:'Let me put the difficult part plainly.',wry:'I have a question. Mercifully, it has no official answer.',practical:'Let us start with what can actually be done.'}[profile.id];
 const recent=c.last?`\n\nTheir own recorded account: ${c.last.slice(0,700)}`:'',account=c.harms[0],terms=account&&repairTerms(account);
 const boundary=account?`“${terms.title}. I need you to ${terms.work}. Company can continue; a pledge or active travel cannot settle this for me.”`:c.review.length?c.ready?'“I have had time to look at the remedy. You can ask what it changes; do not decide my answer for me.”':'“The remedy is recorded. I need two real days before we discuss a new agreement.”':`“${identity.boundary}”`;
 const framing=(p.locationId===s.locationId?`${p.name} makes time for a conversation in ${place}.`:`A letter from ${p.name} in ${place} reaches you in ${here}.`)+(c.relationship==='partner'?' Your shared household leaves room for each person’s separate work.':c.relationship==='courtship'?' Courtship is still a choice; the conversation promises no household pledge.':c.familiarity==='new'?' They keep the exchange small while you are still getting to know one another.':c.familiarity==='trusted'?' Familiarity makes room for a more candid answer.':'');
 const ch=(id,label,description,text,response,effect={})=>({id,label,description,text,response,effect});
 return {nodeId:'person_v29',topic:c.key,title:c.title,body:`${framing} “${opening} ${c.summary}”${c.own?` Their own current work: ${c.own.slice(0,240)}.`:''}${recent}\n\n${boundary}`,choices:[
  ch('ask',account?'Ask what the concrete remedy requires':identity.ask,account?`${terms.days} attended days and ${terms.cost} gold are quoted in their remedy. Listening grants familiarity, not a settlement.`:'Hear this person’s own concern and build familiarity without claiming work or a new agreement.',account?'Tell me which part needs to be put right.':'I want to hear your own answer.',account?`The earlier account is ${account.title}. ${terms.title}: ${terms.work}. That is separate from whether we enjoy each other’s company.`:identity.answer,{bond:account?1:4,memory:`You heard my concern about ${c.title.toLowerCase()}.`}),
  ch('share','Exchange ordinary news','Share ordinary company without resolving a grievance or promising intimacy.','We can leave the larger question open and share our news.',identity.share,{bond:2,memory:`We shared ordinary news while leaving ${c.title.toLowerCase()} in my own hands.`}),
  ch('boundary',c.review.length&&c.ready&&!account?'Ask what the completed remedy changes':'Hear the limit they want to keep',c.review.length&&c.ready&&!account?'They may acknowledge the actual remedy. This neither raises affection nor activates a companion.':'Respect a boundary. No remedy, forgiveness or future agreement is claimed.','What would you like to keep open, and what should wait?',c.review.length&&c.ready&&!account?'I have seen the remedy and can discuss a new agreement. That is not a promise to make one.':account?'I want the recorded remedy before another pledge or journey. We can still speak.':c.review.length?'I need time with the record before another agreement. Speak with me after two real days.':identity.boundary,c.review.length&&c.ready&&!account?{review:true}:{bond:1}),
  ch('leave',p.locationId===s.locationId?'Say goodbye for now':'End the letter for now','No promise or penalty.','We can speak again when you want to.',{kind:'Take care. I am glad we had a little time.',driven:'Bring your next question. I will have one too.',reserved:'Yes. There is no need to decide everything today.',bold:'Good. We have said what needed saying for now.',wry:'Until the next excellent unfinished argument.',practical:'We can come back to the next step when it is needed.'}[profile.id]),
 ]};
}
